import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { signRequest, buildSign, abrirPuerta } from '@/lib/tuya';

// Golden vectors generated by an independent PowerShell implementation
// against the live Tuya API. Exact uppercase-hex equality is required.
const SECRET = 'e3af1d8320e747308660ea1ce9d6d9c2';
const CLIENT_ID = 'gdh8jup8rf9kc5wdqrr7';

describe('Tuya request signing (golden vectors)', () => {
  it('signs the token request (GET, no access token)', () => {
    const sign = signRequest({
      secret: SECRET,
      clientId: CLIENT_ID,
      method: 'GET',
      pathWithQuery: '/v1.0/token?grant_type=1',
      t: '1700000000000',
      nonce: 'fixednoncefortest0001',
    });
    expect(sign).toBe('B28A9140CDEE1494C188E8A87C908E49E1F523069943B0797EA9EBA09779FCCA');
  });

  it('signs an authenticated POST device command', () => {
    const body = '{"commands":[{"code":"switch_1","value":true}]}';
    const sign = signRequest({
      secret: SECRET,
      clientId: CLIENT_ID,
      method: 'POST',
      pathWithQuery: '/v1.0/devices/eb1d3c3608a88b3726itww/commands',
      body,
      accessToken: '8c4688562cf707313e01b931c17e78e9',
      t: '1700000000001',
      nonce: 'fixednoncefortest0002',
    });
    expect(sign).toBe('425D6B06B09ED4D8154AEA0ABE3916B6372186C49324B7BE643D17200098D019');
  });

  it('buildSign returns uppercase hex', () => {
    const sign = buildSign('secret', 'input');
    expect(sign).toMatch(/^[0-9A-F]{64}$/);
  });
});

describe('abrirPuerta when disabled', () => {
  beforeEach(() => {
    vi.stubEnv('TUYA_ENABLED', 'false');
  });

  afterEach(() => {
    vi.unstubAllEnvs();
    vi.restoreAllMocks();
  });

  it('resolves { ok: true, skipped: true } without touching the network', async () => {
    const fetchSpy = vi
      .spyOn(globalThis, 'fetch')
      .mockRejectedValue(new Error('network must not be used'));
    const result = await abrirPuerta();
    expect(result).toEqual({ ok: true, skipped: true });
    expect(fetchSpy).not.toHaveBeenCalled();
  });
});
